ALTER TABLE dbo.PatientResult ADD
    LifecycleStatus NVARCHAR(20) NOT NULL CONSTRAINT DF_PatientResult_LifecycleStatus DEFAULT N'Current',
    SourceType NVARCHAR(20) NOT NULL CONSTRAINT DF_PatientResult_SourceType DEFAULT N'Manual',
    SourceOrganization NVARCHAR(200) NULL,
    SourceSystem NVARCHAR(200) NULL,
    ExternalResultId NVARCHAR(200) NULL,
    ReceivedAtUtc DATETIME2(0) NULL,
    Abnormality NVARCHAR(20) NOT NULL CONSTRAINT DF_PatientResult_Abnormality DEFAULT N'Unknown',
    PreviousResultUid UNIQUEIDENTIFIER NULL,
    EnteredInErrorAtUtc DATETIME2(0) NULL,
    EnteredInErrorBy BIGINT NULL,
    EnteredInErrorReason NVARCHAR(500) NULL;
GO
ALTER TABLE dbo.PatientResult ADD
    CONSTRAINT CK_PatientResult_LifecycleStatus CHECK(LifecycleStatus IN(N'Current',N'Superseded',N'EnteredInError')),
    CONSTRAINT CK_PatientResult_SourceType CHECK(SourceType IN(N'Manual',N'External')),
    CONSTRAINT CK_PatientResult_Abnormality CHECK(Abnormality IN(N'Unknown',N'Normal',N'Abnormal')),
    CONSTRAINT CK_PatientResult_ExternalIdentity CHECK(ExternalResultId IS NULL OR SourceSystem IS NOT NULL),
    CONSTRAINT CK_PatientResult_ExternalSource CHECK(SourceType<>N'External' OR (ReceivedAtUtc IS NOT NULL AND (SourceOrganization IS NOT NULL OR SourceSystem IS NOT NULL))),
    CONSTRAINT CK_PatientResult_ErrorState CHECK((LifecycleStatus<>N'EnteredInError' AND EnteredInErrorAtUtc IS NULL AND EnteredInErrorBy IS NULL AND EnteredInErrorReason IS NULL) OR (LifecycleStatus=N'EnteredInError' AND EnteredInErrorAtUtc IS NOT NULL AND EnteredInErrorBy IS NOT NULL AND EnteredInErrorReason IS NOT NULL)),
    CONSTRAINT FK_PatientResult_Previous FOREIGN KEY(PreviousResultUid) REFERENCES dbo.PatientResult(PatientResultUid),
    CONSTRAINT FK_PatientResult_EnteredInErrorBy FOREIGN KEY(EnteredInErrorBy) REFERENCES dbo.ApplicationUser(UserId);
GO
CREATE UNIQUE INDEX UX_PatientResult_PreviousResultUid ON dbo.PatientResult(PreviousResultUid) WHERE PreviousResultUid IS NOT NULL;
GO
CREATE INDEX IX_PatientResult_ExternalIdentity ON dbo.PatientResult(SourceSystem,ExternalResultId) WHERE ExternalResultId IS NOT NULL;
GO

CREATE OR ALTER PROCEDURE dbo.PatientResult_GetByUid @PatientUid UNIQUEIDENTIFIER,@PatientResultUid UNIQUEIDENTIFIER AS
BEGIN SET NOCOUNT ON; SELECT r.*,cu.DisplayName CreatedByDisplayName,uu.DisplayName UpdatedByDisplayName,ru.DisplayName ReviewedByDisplayName,eu.DisplayName EnteredInErrorByDisplayName FROM dbo.PatientResult r LEFT JOIN dbo.ApplicationUser cu ON cu.UserId=r.CreatedBy LEFT JOIN dbo.ApplicationUser uu ON uu.UserId=r.UpdatedBy LEFT JOIN dbo.ApplicationUser ru ON ru.UserId=r.ReviewedBy LEFT JOIN dbo.ApplicationUser eu ON eu.UserId=r.EnteredInErrorBy WHERE r.PatientUid=@PatientUid AND r.PatientResultUid=@PatientResultUid; END;
GO
CREATE OR ALTER PROCEDURE dbo.PatientResult_GetByPatientUid @PatientUid UNIQUEIDENTIFIER,@StatusFilter NVARCHAR(50)=N'New' AS
BEGIN SET NOCOUNT ON; IF @StatusFilter NOT IN(N'New',N'Reviewed',N'All') SET @StatusFilter=N'New'; SELECT r.*,cu.DisplayName CreatedByDisplayName,uu.DisplayName UpdatedByDisplayName,ru.DisplayName ReviewedByDisplayName,eu.DisplayName EnteredInErrorByDisplayName FROM dbo.PatientResult r LEFT JOIN dbo.ApplicationUser cu ON cu.UserId=r.CreatedBy LEFT JOIN dbo.ApplicationUser uu ON uu.UserId=r.UpdatedBy LEFT JOIN dbo.ApplicationUser ru ON ru.UserId=r.ReviewedBy LEFT JOIN dbo.ApplicationUser eu ON eu.UserId=r.EnteredInErrorBy WHERE r.PatientUid=@PatientUid AND r.LifecycleStatus=N'Current' AND(@StatusFilter=N'All' OR r.ResultStatus=@StatusFilter) ORDER BY r.ResultDate DESC,r.CreatedAt DESC; END;
GO

CREATE OR ALTER PROCEDURE dbo.PatientResult_Create @PatientUid UNIQUEIDENTIFIER,@ResultType NVARCHAR(50),@ResultName NVARCHAR(200),@ResultDate DATETIME2(0),@ResultSummary NVARCHAR(MAX)=NULL,@ResultValue NVARCHAR(500)=NULL,@ResultUnit NVARCHAR(100)=NULL,@ReferenceRange NVARCHAR(200)=NULL,@SourceType NVARCHAR(20)=N'Manual',@SourceOrganization NVARCHAR(200)=NULL,@SourceSystem NVARCHAR(200)=NULL,@ExternalResultId NVARCHAR(200)=NULL,@ReceivedAtUtc DATETIME2(0)=NULL,@Abnormality NVARCHAR(20)=N'Unknown',@CreatedBy BIGINT AS
BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;DECLARE @PatientId BIGINT,@Uid UNIQUEIDENTIFIER=NEWID(); SELECT @PatientId=PatientId FROM dbo.Patient WHERE PatientUid=@PatientUid AND IsDeleted=0;IF @PatientId IS NULL THROW 51300,'Patient not found.',1; EXEC dbo.PatientResult_ValidateFoundation @SourceType,@SourceOrganization,@SourceSystem,@ExternalResultId,@ReceivedAtUtc,@Abnormality;IF NULLIF(LTRIM(RTRIM(@ResultName)),N'') IS NULL THROW 51301,'Result name is required.',1;IF @ResultType NOT IN(N'Lab',N'Imaging',N'Diagnostic Test',N'Other')SET @ResultType=N'Other';BEGIN TRANSACTION;INSERT dbo.PatientResult(PatientResultUid,PatientUid,ResultType,ResultName,ResultDate,ResultSummary,ResultValue,ResultUnit,ReferenceRange,SourceType,SourceOrganization,SourceSystem,ExternalResultId,ReceivedAtUtc,Abnormality,CreatedBy) VALUES(@Uid,@PatientUid,@ResultType,LTRIM(RTRIM(@ResultName)),@ResultDate,NULLIF(@ResultSummary,N''),NULLIF(@ResultValue,N''),NULLIF(@ResultUnit,N''),NULLIF(@ReferenceRange,N''),@SourceType,NULLIF(LTRIM(RTRIM(@SourceOrganization)),N''),NULLIF(LTRIM(RTRIM(@SourceSystem)),N''),NULLIF(LTRIM(RTRIM(@ExternalResultId)),N''),@ReceivedAtUtc,@Abnormality,@CreatedBy);INSERT dbo.AuditLog(UserId,PatientId,ActionName,EntityName,EntityId,NewValue,CreatedAt)VALUES(@CreatedBy,@PatientId,N'ResultCreated',N'PatientResult',CONVERT(NVARCHAR(100),@Uid),N'Status=New;Lifecycle=Current',SYSUTCDATETIME());COMMIT;EXEC dbo.PatientResult_GetByUid @PatientUid,@Uid;END;
GO

CREATE OR ALTER PROCEDURE dbo.PatientResult_ValidateFoundation @SourceType NVARCHAR(20),@SourceOrganization NVARCHAR(200)=NULL,@SourceSystem NVARCHAR(200)=NULL,@ExternalResultId NVARCHAR(200)=NULL,@ReceivedAtUtc DATETIME2(0)=NULL,@Abnormality NVARCHAR(20) AS
BEGIN SET NOCOUNT ON;SET @SourceOrganization=NULLIF(LTRIM(RTRIM(@SourceOrganization)),N'');SET @SourceSystem=NULLIF(LTRIM(RTRIM(@SourceSystem)),N'');SET @ExternalResultId=NULLIF(LTRIM(RTRIM(@ExternalResultId)),N'');IF @SourceType NOT IN(N'Manual',N'External') THROW 51310,'Unsupported Result source type.',1;IF @Abnormality NOT IN(N'Unknown',N'Normal',N'Abnormal') THROW 51311,'Unsupported Result abnormality.',1;IF @ExternalResultId IS NOT NULL AND @SourceSystem IS NULL THROW 51312,'External Result ID requires a source system.',1;IF @SourceType=N'External' AND(@ReceivedAtUtc IS NULL OR(@SourceOrganization IS NULL AND @SourceSystem IS NULL)) THROW 51313,'External Results require received time and source identity.',1;END;
GO

CREATE OR ALTER PROCEDURE dbo.PatientResult_Update @PatientUid UNIQUEIDENTIFIER,@PatientResultUid UNIQUEIDENTIFIER,@ResultType NVARCHAR(50),@ResultName NVARCHAR(200),@ResultDate DATETIME2(0),@ResultSummary NVARCHAR(MAX)=NULL,@ResultValue NVARCHAR(500)=NULL,@ResultUnit NVARCHAR(100)=NULL,@ReferenceRange NVARCHAR(200)=NULL,@SourceType NVARCHAR(20),@SourceOrganization NVARCHAR(200)=NULL,@SourceSystem NVARCHAR(200)=NULL,@ExternalResultId NVARCHAR(200)=NULL,@ReceivedAtUtc DATETIME2(0)=NULL,@Abnormality NVARCHAR(20),@ExpectedRowVersion BINARY(8),@UpdatedBy BIGINT AS
BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;EXEC dbo.PatientResult_ValidateFoundation @SourceType,@SourceOrganization,@SourceSystem,@ExternalResultId,@ReceivedAtUtc,@Abnormality;IF NULLIF(LTRIM(RTRIM(@ResultName)),N'') IS NULL THROW 51301,'Result name is required.',1;IF @ResultType NOT IN(N'Lab',N'Imaging',N'Diagnostic Test',N'Other')SET @ResultType=N'Other';DECLARE @PatientId BIGINT,@Status NVARCHAR(50),@Lifecycle NVARCHAR(20),@CurrentRowVersion BINARY(8);BEGIN TRANSACTION;SELECT @PatientId=p.PatientId,@Status=r.ResultStatus,@Lifecycle=r.LifecycleStatus,@CurrentRowVersion=r.RowVersion FROM dbo.PatientResult r WITH(UPDLOCK,HOLDLOCK) JOIN dbo.Patient p ON p.PatientUid=r.PatientUid WHERE r.PatientUid=@PatientUid AND r.PatientResultUid=@PatientResultUid AND p.IsDeleted=0;IF @PatientId IS NULL BEGIN ROLLBACK;RETURN;END;IF @Status<>N'New' OR @Lifecycle<>N'Current' THROW 51302,'Only current New results can be edited.',1;IF @ExpectedRowVersion<>@CurrentRowVersion THROW 51304,'Result changed before it could be edited.',1;UPDATE dbo.PatientResult SET ResultType=@ResultType,ResultName=LTRIM(RTRIM(@ResultName)),ResultDate=@ResultDate,ResultSummary=NULLIF(@ResultSummary,N''),ResultValue=NULLIF(@ResultValue,N''),ResultUnit=NULLIF(@ResultUnit,N''),ReferenceRange=NULLIF(@ReferenceRange,N''),SourceType=@SourceType,SourceOrganization=NULLIF(LTRIM(RTRIM(@SourceOrganization)),N''),SourceSystem=NULLIF(LTRIM(RTRIM(@SourceSystem)),N''),ExternalResultId=NULLIF(LTRIM(RTRIM(@ExternalResultId)),N''),ReceivedAtUtc=@ReceivedAtUtc,Abnormality=@Abnormality,UpdatedAt=SYSUTCDATETIME(),UpdatedBy=@UpdatedBy WHERE PatientUid=@PatientUid AND PatientResultUid=@PatientResultUid AND RowVersion=@ExpectedRowVersion;INSERT dbo.AuditLog(UserId,PatientId,ActionName,EntityName,EntityId,NewValue,CreatedAt)VALUES(@UpdatedBy,@PatientId,N'ResultUpdated',N'PatientResult',CONVERT(NVARCHAR(100),@PatientResultUid),N'Status=New;Lifecycle=Current',SYSUTCDATETIME());COMMIT;EXEC dbo.PatientResult_GetByUid @PatientUid,@PatientResultUid;END;
GO

CREATE OR ALTER PROCEDURE dbo.PatientResult_Correct @PatientUid UNIQUEIDENTIFIER,@PatientResultUid UNIQUEIDENTIFIER,@ExpectedRowVersion BINARY(8),@ResultType NVARCHAR(50),@ResultName NVARCHAR(200),@ResultDate DATETIME2(0),@ResultSummary NVARCHAR(MAX)=NULL,@ResultValue NVARCHAR(500)=NULL,@ResultUnit NVARCHAR(100)=NULL,@ReferenceRange NVARCHAR(200)=NULL,@SourceType NVARCHAR(20),@SourceOrganization NVARCHAR(200)=NULL,@SourceSystem NVARCHAR(200)=NULL,@ExternalResultId NVARCHAR(200)=NULL,@ReceivedAtUtc DATETIME2(0)=NULL,@Abnormality NVARCHAR(20),@CorrectedBy BIGINT AS
BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;EXEC dbo.PatientResult_ValidateFoundation @SourceType,@SourceOrganization,@SourceSystem,@ExternalResultId,@ReceivedAtUtc,@Abnormality;DECLARE @PatientId BIGINT,@Status NVARCHAR(50),@Lifecycle NVARCHAR(20),@CurrentRowVersion BINARY(8),@NewUid UNIQUEIDENTIFIER=NEWID();BEGIN TRANSACTION;SELECT @PatientId=p.PatientId,@Status=r.ResultStatus,@Lifecycle=r.LifecycleStatus,@CurrentRowVersion=r.RowVersion FROM dbo.PatientResult r WITH(UPDLOCK,HOLDLOCK) JOIN dbo.Patient p ON p.PatientUid=r.PatientUid WHERE r.PatientUid=@PatientUid AND r.PatientResultUid=@PatientResultUid AND p.IsDeleted=0;IF @PatientId IS NULL BEGIN ROLLBACK;RETURN;END;IF @Status<>N'Reviewed' OR @Lifecycle<>N'Current' THROW 51314,'Only current Reviewed results can be corrected.',1;IF @ExpectedRowVersion<>@CurrentRowVersion THROW 51315,'Result changed before it could be corrected.',1;IF EXISTS(SELECT 1 FROM dbo.PatientResult WHERE PreviousResultUid=@PatientResultUid) THROW 51316,'Result already has a correction.',1;INSERT dbo.PatientResult(PatientResultUid,PatientUid,ResultType,ResultName,ResultDate,ResultSummary,ResultValue,ResultUnit,ReferenceRange,SourceType,SourceOrganization,SourceSystem,ExternalResultId,ReceivedAtUtc,Abnormality,PreviousResultUid,CreatedBy)VALUES(@NewUid,@PatientUid,@ResultType,LTRIM(RTRIM(@ResultName)),@ResultDate,NULLIF(@ResultSummary,N''),NULLIF(@ResultValue,N''),NULLIF(@ResultUnit,N''),NULLIF(@ReferenceRange,N''),@SourceType,NULLIF(LTRIM(RTRIM(@SourceOrganization)),N''),NULLIF(LTRIM(RTRIM(@SourceSystem)),N''),NULLIF(LTRIM(RTRIM(@ExternalResultId)),N''),@ReceivedAtUtc,@Abnormality,@PatientResultUid,@CorrectedBy);UPDATE dbo.PatientResult SET LifecycleStatus=N'Superseded',UpdatedAt=SYSUTCDATETIME(),UpdatedBy=@CorrectedBy WHERE PatientUid=@PatientUid AND PatientResultUid=@PatientResultUid AND RowVersion=@ExpectedRowVersion;INSERT dbo.AuditLog(UserId,PatientId,ActionName,EntityName,EntityId,NewValue,CreatedAt)VALUES(@CorrectedBy,@PatientId,N'ResultCorrected',N'PatientResult',CONVERT(NVARCHAR(100),@PatientResultUid),N'ReplacementUid='+CONVERT(NVARCHAR(100),@NewUid),SYSUTCDATETIME());COMMIT;EXEC dbo.PatientResult_GetByUid @PatientUid,@NewUid;END;
GO

CREATE OR ALTER PROCEDURE dbo.PatientResult_MarkEnteredInError @PatientUid UNIQUEIDENTIFIER,@PatientResultUid UNIQUEIDENTIFIER,@ExpectedRowVersion BINARY(8),@Reason NVARCHAR(500),@Actor BIGINT AS
BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;IF NULLIF(LTRIM(RTRIM(@Reason)),N'') IS NULL THROW 51317,'Entered-in-error reason is required.',1;DECLARE @PatientId BIGINT,@Lifecycle NVARCHAR(20),@CurrentRowVersion BINARY(8),@Now DATETIME2(0)=SYSUTCDATETIME();BEGIN TRANSACTION;SELECT @PatientId=p.PatientId,@Lifecycle=r.LifecycleStatus,@CurrentRowVersion=r.RowVersion FROM dbo.PatientResult r WITH(UPDLOCK,HOLDLOCK) JOIN dbo.Patient p ON p.PatientUid=r.PatientUid WHERE r.PatientUid=@PatientUid AND r.PatientResultUid=@PatientResultUid AND p.IsDeleted=0;IF @PatientId IS NULL BEGIN ROLLBACK;RETURN;END;IF @Lifecycle<>N'Current' THROW 51318,'Only a current Result can be marked entered in error.',1;IF @ExpectedRowVersion<>@CurrentRowVersion THROW 51319,'Result changed before it could be marked entered in error.',1;UPDATE dbo.PatientResult SET LifecycleStatus=N'EnteredInError',EnteredInErrorAtUtc=@Now,EnteredInErrorBy=@Actor,EnteredInErrorReason=LTRIM(RTRIM(@Reason)),UpdatedAt=@Now,UpdatedBy=@Actor WHERE PatientUid=@PatientUid AND PatientResultUid=@PatientResultUid AND RowVersion=@ExpectedRowVersion;INSERT dbo.AuditLog(UserId,PatientId,ActionName,EntityName,EntityId,NewValue,CreatedAt)VALUES(@Actor,@PatientId,N'ResultEnteredInError',N'PatientResult',CONVERT(NVARCHAR(100),@PatientResultUid),N'Lifecycle=EnteredInError',@Now);COMMIT;EXEC dbo.PatientResult_GetByUid @PatientUid,@PatientResultUid;END;
GO

CREATE OR ALTER PROCEDURE dbo.PatientResult_GetHistory @PatientUid UNIQUEIDENTIFIER,@PatientResultUid UNIQUEIDENTIFIER AS
BEGIN SET NOCOUNT ON;DECLARE @Root UNIQUEIDENTIFIER=@PatientResultUid,@Previous UNIQUEIDENTIFIER;SELECT @Previous=PreviousResultUid FROM dbo.PatientResult WHERE PatientUid=@PatientUid AND PatientResultUid=@Root;WHILE @Previous IS NOT NULL BEGIN SET @Root=@Previous;SELECT @Previous=PreviousResultUid FROM dbo.PatientResult WHERE PatientUid=@PatientUid AND PatientResultUid=@Root;END;WITH Lineage AS(SELECT r.*,0 Depth FROM dbo.PatientResult r WHERE r.PatientUid=@PatientUid AND r.PatientResultUid=@Root UNION ALL SELECT n.*,l.Depth+1 FROM dbo.PatientResult n JOIN Lineage l ON n.PreviousResultUid=l.PatientResultUid WHERE n.PatientUid=@PatientUid)SELECT l.*,cu.DisplayName CreatedByDisplayName,ru.DisplayName ReviewedByDisplayName,eu.DisplayName EnteredInErrorByDisplayName FROM Lineage l LEFT JOIN dbo.ApplicationUser cu ON cu.UserId=l.CreatedBy LEFT JOIN dbo.ApplicationUser ru ON ru.UserId=l.ReviewedBy LEFT JOIN dbo.ApplicationUser eu ON eu.UserId=l.EnteredInErrorBy ORDER BY Depth OPTION(MAXRECURSION 100);END;
GO

CREATE OR ALTER PROCEDURE dbo.PatientResult_GetUnreviewedCount AS BEGIN SET NOCOUNT ON;SELECT COUNT_BIG(*) FROM dbo.PatientResult r JOIN dbo.Patient p ON p.PatientUid=r.PatientUid WHERE r.ResultStatus=N'New' AND r.ReviewedAt IS NULL AND r.LifecycleStatus=N'Current' AND p.IsDeleted=0;END;
GO
CREATE OR ALTER PROCEDURE dbo.PatientResult_GetUnreviewed AS BEGIN SET NOCOUNT ON;SELECT r.PatientResultUid,r.PatientUid,CONCAT(p.FirstName,N' ',p.LastName) PatientDisplayName,p.ChartNumber,r.ResultType,r.ResultName,r.ResultDate,r.ResultSummary,r.ResultValue,r.ResultUnit,r.ReferenceRange,r.ResultStatus,r.SourceType,r.SourceOrganization,r.SourceSystem,r.Abnormality,r.CreatedAt,r.RowVersion FROM dbo.PatientResult r JOIN dbo.Patient p ON p.PatientUid=r.PatientUid WHERE r.ResultStatus=N'New' AND r.ReviewedAt IS NULL AND r.LifecycleStatus=N'Current' AND p.IsDeleted=0 ORDER BY r.ResultDate,r.CreatedAt;END;
GO

CREATE OR ALTER PROCEDURE dbo.PatientResult_MarkReviewed @PatientUid UNIQUEIDENTIFIER,@PatientResultUid UNIQUEIDENTIFIER,@ReviewNote NVARCHAR(1000)=NULL,@ReviewedBy BIGINT,@ExpectedRowVersion BINARY(8) AS
BEGIN SET NOCOUNT ON;SET XACT_ABORT ON;IF NOT EXISTS(SELECT 1 FROM dbo.ApplicationUser WHERE UserId=@ReviewedBy AND IsActive=1)THROW 51303,'Active clinical reviewer not found.',1;BEGIN TRANSACTION;DECLARE @CurrentStatus NVARCHAR(50),@Lifecycle NVARCHAR(20),@CurrentReviewedAt DATETIME2(0),@CurrentRowVersion BINARY(8),@PatientId BIGINT,@ReviewWasApplied BIT=0;SELECT @CurrentStatus=r.ResultStatus,@Lifecycle=r.LifecycleStatus,@CurrentReviewedAt=r.ReviewedAt,@CurrentRowVersion=r.RowVersion,@PatientId=p.PatientId FROM dbo.PatientResult r WITH(UPDLOCK,HOLDLOCK) JOIN dbo.Patient p ON p.PatientUid=r.PatientUid WHERE r.PatientUid=@PatientUid AND r.PatientResultUid=@PatientResultUid;IF @PatientId IS NULL BEGIN ROLLBACK;RETURN;END;IF @Lifecycle<>N'Current' THROW 51320,'Only a current Result can be reviewed.',1;IF @CurrentStatus=N'New' AND @CurrentReviewedAt IS NULL BEGIN IF @ExpectedRowVersion<>@CurrentRowVersion THROW 51304,'Result changed before it could be reviewed.',1;DECLARE @Now DATETIME2(0)=SYSUTCDATETIME();UPDATE dbo.PatientResult SET ResultStatus=N'Reviewed',ReviewedAt=@Now,ReviewedBy=@ReviewedBy,ReviewNote=NULLIF(LTRIM(RTRIM(@ReviewNote)),N''),UpdatedAt=@Now,UpdatedBy=@ReviewedBy WHERE PatientUid=@PatientUid AND PatientResultUid=@PatientResultUid AND RowVersion=@ExpectedRowVersion;INSERT dbo.AuditLog(UserId,PatientId,ActionName,EntityName,EntityId,NewValue,CreatedAt)VALUES(@ReviewedBy,@PatientId,N'ResultReviewed',N'PatientResult',CONVERT(NVARCHAR(100),@PatientResultUid),N'Status=Reviewed',@Now);SET @ReviewWasApplied=1;END;COMMIT;SELECT r.*,cu.DisplayName CreatedByDisplayName,uu.DisplayName UpdatedByDisplayName,ru.DisplayName ReviewedByDisplayName,eu.DisplayName EnteredInErrorByDisplayName,@ReviewWasApplied ReviewWasApplied FROM dbo.PatientResult r LEFT JOIN dbo.ApplicationUser cu ON cu.UserId=r.CreatedBy LEFT JOIN dbo.ApplicationUser uu ON uu.UserId=r.UpdatedBy LEFT JOIN dbo.ApplicationUser ru ON ru.UserId=r.ReviewedBy LEFT JOIN dbo.ApplicationUser eu ON eu.UserId=r.EnteredInErrorBy WHERE r.PatientUid=@PatientUid AND r.PatientResultUid=@PatientResultUid;END;
GO
